    o = sync_order(h)
    se = spatial_entropy(h)
    te = temporal_entropy(h)
    ent = 0.55 * se + 0.45 * te
    sens = sensitivity_proxy(N, r, eps, method=method, N_fast=N_fast, f_fast=f_fast)
    bd = edge_density(h)
